/*
 * A009112  Areas of Pythagorean triangles: numbers which can be the area of a
 *          right triangle with integer sides.
 * https://oeis.org/A009112
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = the nth smallest integer that can be the area of a right
 *            triangle with integer sides. The sequence is generated by
 *            enumerating all primitive Pythagorean triples (m,n) and then
 *            repeatedly inserting k²·area_primitive into a min‑heap; the heap
 *            always yields the next smallest unique area
 * Range:     u8 none, u16 none, u32 n <= 2390, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   gcd_int
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include "../utils/gcd_int.h"

/* Node in the min‑heap. */
typedef struct {
    seq_t area;   /* current area equal to area0 * k² */
    seq_t area0;  /* area of the primitive triple */
    unsigned k;   /* current multiplier */
} node_t;

/* Swap two heap nodes. */
static inline void heap_swap(node_t *a, node_t *b) {
    node_t temp = *a;
    *a = *b;
    *b = temp;
}

/* Upward heapify. */
static void heapify_up(node_t *data, size_t idx) {
    while (idx > 0) {
        size_t parent = (idx - 1) >> 1;
        if (data[parent].area <= data[idx].area)
            break;
        heap_swap(&data[parent], &data[idx]);
        idx = parent;
    }
}

/* Downward heapify. */
static void heapify_down(node_t *data, size_t idx, size_t heap_len) {
    for (;;) {
        size_t left = (idx << 1) + 1;
        if (left >= heap_len) break;
        size_t smallest = left;
        size_t right = left + 1;
        if (right < heap_len && data[right].area < data[left].area)
            smallest = right;
        if (data[idx].area <= data[smallest].area)
            break;
        heap_swap(&data[idx], &data[smallest]);
        idx = smallest;
    }
}

/* GCD for small integers. */

/* Sequence storage. */
static seq_t *seq_arr = NULL;
static size_t seq_len = 0;
static size_t seq_cap = 0;

/* Heap storage. */
static node_t *heap_data = NULL;
static size_t heap_len = 0;
static size_t heap_cap = 0;

/* Flag indicating whether the data structures have been initialized. */
static int initialized = 0;

/* Pre‑compute primitive triples (up to M) and fill the heap. */
static void init_primatives(void) {
    const unsigned M = 600;  /* sufficient for n up to about 10 000 */
    /* Rough estimate of the number of primaries: 0.6*M*M */
    heap_cap = (size_t)(0.7 * M * M) + 10;
    heap_data = (node_t *)malloc(sizeof(node_t) * heap_cap);
    heap_len = 0;

    for (unsigned m = 2; m <= M; ++m) {
        unsigned m_parity = m & 1;
        for (unsigned n = 1; n < m; ++n) {
            if ((n & 1) == m_parity) continue;          /* opposite parity required */
            if (gcd_int((int)m, (int)n) != 1) continue;   /* coprime */
            seq_t m_val = (seq_t)m;
            seq_t n_val = (seq_t)n;
            seq_t m2 = m_val * m_val;
            seq_t n2 = n_val * n_val;
            seq_t diff = m2 - n2;
            seq_t area0 = m_val * n_val * diff;          /* primitive area */
            if (heap_len == heap_cap) {                 /* grow heap if needed */
                heap_cap *= 2;
                heap_data = (node_t *)realloc(heap_data, sizeof(node_t) * heap_cap);
            }
            heap_data[heap_len++] = (node_t){area0, area0, 1};
        }
    }

    /* Build the heap in O(N). */
    for (size_t i = (heap_len >> 1); i-- > 0; ) {
        heapify_down(heap_data, i, heap_len);
    }

    /* Prepare sequence array. */
    seq_cap = 256;
    seq_arr = (seq_t *)malloc(sizeof(seq_t) * seq_cap);
}

/* Generate terms until we have at least n terms. */
static void generate_upto(idx_t n) {
    while (seq_len < n) {
        /* Pop smallest area from the heap. */
        node_t top = heap_data[0];
        heap_data[0] = heap_data[--heap_len];
        heapify_down(heap_data, 0, heap_len);

        seq_t area = top.area;

        /* Store if not a duplicate. */
        if (seq_len == 0 || area != seq_arr[seq_len - 1]) {
            if (seq_len == seq_cap) {
                seq_cap *= 2;
                seq_arr = (seq_t *)realloc(seq_arr, sizeof(seq_t) * seq_cap);
            }
            seq_arr[seq_len++] = area;
        }

        /* Insert next multiple of the same primitive. */
        unsigned nk = top.k + 1;
        seq_t kk = (seq_t)nk * nk;          /* k² */
        seq_t new_area = top.area0 * kk;
        if (heap_len == heap_cap) {         /* grow heap if needed */
            heap_cap *= 2;
            heap_data = (node_t *)realloc(heap_data, sizeof(node_t) * heap_cap);
        }
        heap_data[heap_len++] = (node_t){new_area, top.area0, nk};
        heapify_up(heap_data, heap_len - 1);
    }
}

seq_t a(idx_t n) {
    if (!initialized) {
        init_primatives();
        initialized = 1;
    }
    if (n == 0) return 0;          /* safety, offset is 1 */
    generate_upto(n);
    return seq_arr[n - 1];
}
